279	    /**
280	     * Whether this owner has been soft-deleted. A newly created owner is not deleted; the delete
281	     * endpoint flags this true and retains the row rather than removing it. Deleted owners are
282	     * ignored by the create endpoint's duplicate and identity checks.
283	     */
284	    public boolean isDeleted() {
285	        return this.deleted;
286	    }
287	
288	    public void setDeleted(boolean deleted) {
289	        this.deleted = deleted;
290	    }
291	
292	    /**
293	     * The owner's membership points, derived on read: they start at 0, add 2 when an email is
294	     * present, add 1 when {@link #namesakeCount} is 0, add 2 for a household of 3 or more
295	     * ({@link #householdMemberCount}), and add 3 for tenure over one fiscal year (elapsed fiscal
296	     * years from {@link #registrationDate} to today; see {@link #hasTenureBonus(LocalDate)}).
297	     */
298	    @Transient
299	    public Integer getMembershipPoints() {
300	        return membershipPoints(this.email, this.namesakeCount, this.householdMemberCount,
301	            this.registrationDate);
302	    }
303	
304	    /**
305	     * The owner's numeric membership level, derived on read from {@link #getMembershipPoints()}:
306	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more; then held down to the owner's
307	     * {@link #getMembershipLevelCap() membership level cap} when one has been assigned.
308	     */
309	    @Transient
310	    public Integer getMembershipLevel() {
311	        return capMembershipLevel(membershipLevel(getMembershipPoints()), this.membershipLevelCap);
312	    }
313	
314	    /** The membership points derived from the given factors: they start at 0, add 2 when
315	     *  {@code email} is present, add 1 when {@code namesakeCount} is 0, add 2 for a household of 3 or
316	     *  more ({@code householdMemberCount}), and add 3 for sufficient tenure (see
317	     *  {@link #hasTenureBonus(LocalDate)}). */
318	    private static int membershipPoints(String email, Integer namesakeCount,
319	            Integer householdMemberCount, LocalDate registrationDate) {
320	        int points = 0;
321	        if (email != null && !email.isBlank()) {
322	            points += 2;
323	        }
324	        if (namesakeCount != null && namesakeCount == 0) {
325	            points += 1;
326	        }
327	        if (householdMemberCount != null && householdMemberCount >= 3) {
328	            points += 2;
329	        }
330	        if (hasTenureBonus(registrationDate)) {
331	            points += 3;
332	        }
333	        return points;
334	    }
335	
336	    /** Whether the owner's tenure earns the membership tenure bonus: the elapsed fiscal years from
337	     *  {@code registrationDate} to today exceed one, i.e. the registration falls two or more fiscal
338	     *  years before the current one (fiscal years start 1 July). A null registration date earns no
339	     *  bonus. */
340	    private static boolean hasTenureBonus(LocalDate registrationDate) {
341	        return registrationDate != null
342	            && fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) > 1;
343	    }
344	
345	    /**
346	     * The fiscal year (starting 1 July) that contains {@code date}, identified by the calendar year
347	     * in which that fiscal year ends: a date in July-December belongs to the fiscal year ending the
348	     * following calendar year, and a date in January-June to the fiscal year ending that same year
349	     * (e.g. 2026-09-05 -> 2027, 2026-03-01 -> 2026).
350	     */
351	    public static int fiscalYear(LocalDate date) {
352	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
353	    }
354	
355	    /**
356	     * The two-digit fiscal-year segment for {@code date}: the last two digits of the fiscal year
357	     * (starting 1 July) that contains it, zero-padded (e.g. a date of 2026-09-05 falls in fiscal year
358	     * 2027 -> {@code "27"}). This is the bare numeric segment behind the {@code "FY"}-prefixed
359	     * {@link #getFiscalYear()} and is also the segment the controller stamps into an owner's
360	     * identifier; the fiscal-year rule itself lives in {@link #fiscalYear(LocalDate)} and is shared,
361	     * not duplicated.
362	     */
363	    public static String fiscalYearSegment(LocalDate date) {
364	        return String.format("%02d", fiscalYear(date) % 100);
365	    }
366	
367	    /**
368	     * The owner's fiscal year, derived on read from the (business-day-adjusted)
369	     * {@link #registrationDate} as {@code "FY<YY>"}, where YY is the two-digit
370	     * {@link #fiscalYearSegment(LocalDate) fiscal-year segment} of the registration date (e.g. a date
371	     * of 2026-09-05 yields {@code "FY27"}). Returns {@code null} when no registration date is
372	     * available.
373	     */
374	    @Transient
375	    public String getFiscalYear() {
376	        if (this.registrationDate == null) {
377	            return null;
378	        }
379	        return "FY" + fiscalYearSegment(this.registrationDate);
380	    }
381	
382	    /** The numeric membership level (1-4) mapped from membership points: 1 for 0-1 points, 2 for
383	     *  2-3, 3 for 4-5, and 4 for 6 or more. */
384	    private static int membershipLevel(int points) {
385	        if (points >= 6) {
386	            return 4;
387	        }
388	        if (points >= 4) {
389	            return 3;
390	        }
391	        if (points >= 2) {
392	            return 2;
393	        }
394	        return 1;
395	    }
396	
397	    /** The membership {@code level} held down to {@code cap}, i.e. the smaller of the two, when a cap
398	     *  is present; the level unchanged when {@code cap} is {@code null} and no ceiling applies. */
399	    private static int capMembershipLevel(int level, Integer cap) {
400	        return cap == null ? level : Math.min(level, cap);
401	    }
402	
403	    /**
404	     * The owner's preferred contact channel, derived on read: {@code "EMAIL"} when an email is
405	     * present, otherwise {@code "PHONE"}.
406	     */
407	    @Transient
408	    public String getContactPreference() {
409	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
410	    }
411	
412	    /**
413	     * The owner's age band, derived on read from the {@link #birthDate} relative to the
414	     * {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18 to 64, and
415	     * {@code "SENIOR"} at 65 or over. Returns {@code null} when no birth date (or no registration
416	     * date to measure against) is available.
417	     */
418	    @Transient
419	    public String getAgeBand() {
420	        if (this.birthDate == null || this.registrationDate == null) {
421	            return null;
422	        }
423	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
424	        if (age < 18) {
425	            return "MINOR";
426	        }
427	        if (age < 65) {
428	            return "ADULT";
429	        }
430	        return "SENIOR";
431	    }
432	
433	    /**
434	     * The single Luhn check digit (0-9) computed over the decimal digits contained in the
435	     * {@link #customerCode}, derived on read.
436	     */
437	    @Transient
438	    public Integer getCheckDigit() {
439	        return luhnCheckDigit(this.customerCode);
440	    }
441	
442	    /** Region -> inclusive 4-digit postcode range {low, high}, used to derive the region from the
443	     *  postcode ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
444	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
445	        "NSW", new int[] {2000, 2099},
446	        "VIC", new int[] {3000, 3099},
447	        "QLD", new int[] {4000, 4099});
448	
449	    /**
450	     * The owner's region, derived on read. The postcode is preferred: a 4-digit postcode falling in a
451	     * known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}) yields
452	     * that region. When the postcode is absent or in no known range, it falls back to the fixed
453	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
454	     * Returns {@code "UNKNOWN"} when neither source resolves a region.
455	     */
456	    @Transient
457	    public String getRegion() {
458	        String byPostcode = regionForPostcode(this.postcode);
459	        if (byPostcode != null) {
460	            return byPostcode;
461	        }
462	        if ("Sydney".equals(this.city)) {
463	            return "NSW";
464	        }
465	        if ("Melbourne".equals(this.city)) {
466	            return "VIC";
467	        }
468	        if ("Brisbane".equals(this.city)) {
469	            return "QLD";
470	        }
471	        return "UNKNOWN";
472	    }
473	
474	    /**
475	     * The owner's locality, derived on read from the region-and-hash {@link #getCustomerCode()
476	     * customer code}: the region segment before the first '-' of the customer code
477	     * ('<REGION>-<HASH8>'). Falls back to the owner's {@link #getRegion() region} when no customer
478	     * code has been assigned yet.
479	     */
480	    @Transient
481	    public String getLocality() {
482	        if (this.customerCode != null) {
483	            int dash = this.customerCode.indexOf('-');
484	            if (dash > 0) {
485	                return this.customerCode.substring(0, dash);
486	            }
487	        }
488	        return getRegion();
489	    }
490	
491	    /** Region -> IANA timezone name, the fixed region-to-timezone table ({@code NSW ->
492	     *  Australia/Sydney}, {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). */
493	    private static final Map<String, String> REGION_TIMEZONES = Map.of(
494	        "NSW", "Australia/Sydney",
495	        "VIC", "Australia/Melbourne",
496	        "QLD", "Australia/Brisbane");
497	
498	    /**
499	     * The owner's timezone, derived on read as the IANA name for the owner's
500	     * {@link #getLocality() locality/region} via the fixed region-to-timezone table
501	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
502	     * {@code QLD -> Australia/Brisbane}). Returns {@code null} when the region carries no entry in
503	     * the table (e.g. {@code UNKNOWN}).
504	     */
505	    @Transient
506	    public String getTimezone() {
507	        return timezoneForRegion(getLocality());
508	    }
509	
510	    /**
511	     * The owner's segment, derived on read as {@code "<TIER>_<AREA>"}: one of {@code "PREMIUM_METRO"},
512	     * {@code "PREMIUM_REGIONAL"}, {@code "STANDARD_METRO"} or {@code "STANDARD_REGIONAL"}. TIER is
513	     * {@code "PREMIUM"} when the {@link #getMembershipLevel() membership level} is 3 or more, otherwise
514	     * {@code "STANDARD"}. AREA is {@code "METRO"} when the {@link #getLocality() locality} is a known
515	     * region ({@code NSW}, {@code VIC} or {@code QLD}), otherwise {@code "REGIONAL"}.
516	     */
517	    @Transient
518	    public String getOwnerSegment() {
519	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
520	        String area = REGION_POSTCODE_RANGES.containsKey(getLocality()) ? "METRO" : "REGIONAL";
521	        return tier + "_" + area;
522	    }
523	
524	    /** The IANA timezone name for {@code region} via the fixed region-to-timezone table, or
525	     *  {@code null} when the region carries no entry ({@code NSW -> Australia/Sydney},
526	     *  {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). */
527	    public static String timezoneForRegion(String region) {
528	        return REGION_TIMEZONES.get(region);
529	    }
530	
531	    /** The inclusive 4-digit postcode {@code {low, high}} range for {@code region}, or {@code null} when
532	     *  the region carries no range rule (i.e. {@code UNKNOWN} or any region absent from the table:
533	     *  {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
534	    public static int[] postcodeRangeForRegion(String region) {
535	        return REGION_POSTCODE_RANGES.get(region);
536	    }
537	
538	    /** The region whose postcode range contains {@code postcode}, or {@code null} when the postcode is
539	     *  absent, not a 4-digit value, or in no known range. */
540	    private static String regionForPostcode(String postcode) {
541	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
542	            return null;
543	        }
544	        int value = Integer.parseInt(postcode);
545	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
546	            int[] range = entry.getValue();
547	            if (value >= range[0] && value <= range[1]) {
548	                return entry.getKey();
549	            }
550	        }
551	        return null;
552	    }
553	
554	    /** Telephone country code -> the national-number length it requires ({@code +61} Australia => 9
555	     *  digits, {@code +1} NANP => 10), used to derive telephone values from the stored E.164 number.
556	     *  The country codes here carry no conflicting prefixes ({@code +61} does not start with
557	     *  {@code +1}), so a number matches at most one. */
558	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
559	        "+61", 9, "+1", 10);
560	
561	    /**
562	     * The stored E.164 {@link #telephone} formatted for humans, derived on read: the country code, a
563	     * space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}). Falls back
564	     * to the raw value when it is {@code null} or begins with no recognised country code.
565	     */
566	    @Transient
567	    public String getTelephoneDisplay() {
568	        if (this.telephone == null) {
569	            return null;
570	        }
571	        String countryCode = countryCodeOf(this.telephone);
572	        if (countryCode == null) {
573	            return this.telephone;
574	        }
575	        String national = this.telephone.substring(countryCode.length());
576	        StringBuilder grouped = new StringBuilder(countryCode);
577	        for (int i = 0; i < national.length(); i++) {
578	            if (i % 3 == 0) {
579	                grouped.append(' ');
580	            }
581	            grouped.append(national.charAt(i));
582	        }
583	        return grouped.toString();
584	    }
585	
586	    /** The recognised telephone country code that {@code telephone} begins with (e.g. {@code "+61"}),
587	     *  or {@code null} when it is {@code null} or begins with no recognised country code. */
588	    public static String countryCodeOf(String telephone) {
589	        if (telephone == null) {
590	            return null;
591	        }
592	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
593	            if (telephone.startsWith(countryCode)) {
594	                return countryCode;
595	            }
596	        }
597	        return null;
598	    }
599	
600	    /** The national-number length required for {@code countryCode}, or {@code null} when the country
601	     *  code carries no length rule (i.e. any code absent from the table: {@code +61 => 9},
602	     *  {@code +1 => 10}). */
603	    public static Integer nationalNumberLength(String countryCode) {
604	        return NATIONAL_NUMBER_LENGTHS.get(countryCode);
605	    }
606	
607	    /** The single Luhn check digit (0-9) over the decimal digits contained in {@code value}, scanning
608	     *  right to left and doubling every second digit; non-digit characters are ignored and a null or
609	     *  digit-free value yields {@code 0}. Shared by the derived {@link #getCheckDigit()} and the
610	     *  controller that stamps a check digit into an owner's identifier, so the Luhn rule lives here
611	     *  once and is not duplicated. */
612	    public static int luhnCheckDigit(String value) {
613	        int sum = 0;
614	        boolean doubling = true;
615	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
616	            char c = value.charAt(i);
617	            if (c < '0' || c > '9') {
618	                continue;
619	            }
620	            int digit = c - '0';
621	            if (doubling) {
622	                digit *= 2;
623	                if (digit > 9) {
624	                    digit -= 9;
625	                }
626	            }
627	            sum += digit;
628	            doubling = !doubling;
629	        }
630	        return (10 - (sum % 10)) % 10;
631	    }
632	
633	    /** The upper-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters; the
634	     *  upper-case rendering of {@link #sha256HexLower(String)}. */
635	    public static String sha256Hex(String input) {
636	        return sha256HexLower(input).toUpperCase(Locale.ROOT);
637	    }
638	
639	    /** The lower-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters. */
640	    public static String sha256HexLower(String input) {
641	        try {
642	            byte[] digest = MessageDigest.getInstance("SHA-256")
643	                .digest(input.getBytes(StandardCharsets.UTF_8));
644	            StringBuilder sb = new StringBuilder(digest.length * 2);
645	            for (byte b : digest) {
646	                sb.append(String.format("%02x", b));
647	            }
648	            return sb.toString();
649	        }
650	        catch (NoSuchAlgorithmException e) {
651	            throw new IllegalStateException("SHA-256 not available", e);
652	        }
653	    }
654	
655	    protected Set<Pet> getPetsInternal() {
656	        if (this.pets == null) {
657	            this.pets = new HashSet<>();
658	        }
659	        return this.pets;
660	    }
661	
662	    protected void setPetsInternal(Set<Pet> pets) {
663	        this.pets = pets;
664	    }
665	
666	    public List<Pet> getPets() {
667	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
668	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
669	        return Collections.unmodifiableList(sortedPets);
670	    }
671	
672	    public void setPets(List<Pet> pets) {
673	        this.pets = new HashSet<>(pets);
674	    }
675	
676	    public void addPet(Pet pet) {
677	        getPetsInternal().add(pet);
678	        pet.setOwner(this);
679	    }
680	
681	    /**
682	     * Return the Pet with the given name, or null if none found for this Owner.
683	     *
684	     * @param name to test
685	     * @return true if pet name is already in use
686	     */
687	    public Pet getPet(String name) {
688	        return getPet(name, false);
689	    }
690	
691	    /**
692	     * Return the Pet with the given name, or null if none found for this Owner.
693	     *
694	     * @param name to test
695	     * @return true if pet name is already in use
696	     */
697	    public Pet getPet(String name, boolean ignoreNew) {
698	        name = name.toLowerCase();
699	        for (Pet pet : getPetsInternal()) {
700	            if (!ignoreNew || !pet.isNew()) {
701	                String compName = pet.getName();
702	                compName = compName.toLowerCase();
703	                if (compName.equals(name)) {
704	                    return pet;
705	                }
706	            }
707	        }
708	        return null;
709	    }
710	
711	    public Pet getPet(Integer petId) {
712	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
713	    }
714	
715	    @Override
716	    public String toString() {
717	        return new ToStringCreator(this)
718	
719	            .append("id", this.getId())
720	            .append("new", this.isNew())
721	            .append("lastName", this.getLastName())
722	            .append("firstName", this.getFirstName())
723	            .append("address", this.address)
724	            .append("city", this.city)
725	            .append("telephone", this.telephone)
726	            .toString();
727	    }
728	}
