237	    /**
238	     * Canonicalize an incoming owner's submitted contact and address fields into their stored forms
239	     * and validate them, returning whether the owner may proceed to creation. On success the owner's
240	     * address, email (when supplied) and telephone are replaced with their normalized values. Returns
241	     * {@code false} - so the caller can reject the request with {@code 400 BAD_REQUEST} - when the
242	     * address is blank after normalization, a supplied email is not syntactically valid, the postcode
243	     * is not acceptable for the owner's city, or the telephone cannot form a valid E.164 number.
244	     */
245	    private boolean normalizeAndValidateFields(Owner owner) {
246	        if (!normalizeAddressFields(owner)) {
247	            return false;
248	        }
249	        if (owner.getEmail() != null) {
250	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
251	            if (!EMAIL_PATTERN.matcher(email).matches()) {
252	                return false;
253	            }
254	            if (isDisposableEmailDomain(email)) {
255	                return false;
256	            }
257	            owner.setEmail(email);
258	        }
259	        if (!isPostcodeValidForCity(owner)) {
260	            return false;
261	        }
262	        String telephone = normalizeTelephone(owner.getTelephone());
263	        if (telephone == null) {
264	            return false;
265	        }
266	        owner.setTelephone(telephone);
267	        return true;
268	    }
