270	    /**
271	     * Canonicalize an incoming owner's submitted address into its stored form and validate it,
272	     * returning whether the owner may proceed to creation. The structured fields are preferred when
273	     * present: when {@code addressLine1} is non-blank the structured lines are each normalized
274	     * ({@link #normalizeAddress}) and written back, and the flat {@code address} is set to the
275	     * composed value (the normalized addressLine1, with a single space and the normalized
276	     * addressLine2 appended when addressLine2 is present). Otherwise the flat {@code address} is
277	     * normalized and written back for backward compatibility. Returns {@code false} - so the caller
278	     * can reject the request with {@code 400 BAD_REQUEST} - when neither form supplies a non-blank
279	     * address. This is the single place the owner's address is read, canonicalized and written back,
280	     * mirroring the per-concern normalization the email, postcode and telephone steps each own.
281	     */
282	    private boolean normalizeAddressFields(Owner owner) {
283	        String line1 = normalizeAddress(owner.getAddressLine1());
284	        if (!line1.isEmpty()) {
285	            String line2 = normalizeAddress(owner.getAddressLine2());
286	            owner.setAddressLine1(line1);
287	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
288	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
289	            return true;
290	        }
291	        String address = normalizeAddress(owner.getAddress());
292	        if (address.isEmpty()) {
293	            return false;
294	        }
295	        owner.setAddress(address);
296	        return true;
297	    }
298	
299	    /**
300	     * Whether {@code email}'s domain (the part after the last '@') is on the disposable-domain
301	     * blocklist, compared case-insensitively. The email is already normalized to lower case by the
302	     * caller, so a simple membership test against {@link #DISPOSABLE_EMAIL_DOMAINS} suffices.
303	     */
304	    private static boolean isDisposableEmailDomain(String email) {
305	        int at = email.lastIndexOf('@');
306	        if (at < 0) {
307	            return false;
308	        }
309	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
310	    }
