312	    /**
313	     * Build the response DTO for a single owner, attaching the per-response derived flags that are
314	     * computed against the owner population rather than carried on the owner itself (currently the
315	     * {@code bulkSignupWarning}). Used by the single-owner read and create endpoints; the collection
316	     * listing intentionally omits these flags.
317	     */
318	    private OwnerDto buildOwnerDto(Owner owner) {
319	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
320	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
321	        ownerDto.setCapacityWarning(isCapacityWarning(owner));
322	        return ownerDto;
323	    }
324	
325	    /**
326	     * Whether {@code owner}'s city is approaching its per-city capacity limit: it already holds between
327	     * 40 and 49 other owners, one short of the hard limit of 50 at which creation is rejected.
328	     * Surfaced on responses as {@code capacityWarning}. Computed against the current owner population
329	     * excluding this owner, so the count basis mirrors the per-city create gate (which counts the
330	     * owners already present, before the new one is added).
331	     */
332	    private boolean isCapacityWarning(Owner owner) {
333	        long othersInCity = countOtherOwnersInCity(owner);
334	        return othersInCity >= 40 && othersInCity < 50;
335	    }
336	
