426	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
427	    @Override
428	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
429	        Owner owner = this.clinicService.findOwnerById(ownerId);
430	        if (owner != null) {
431	            Pet pet = owner.getPet(petId);
432	            if (pet != null) {
433	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
434	            }
435	        }
436	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
437	    }
438	
439	    /** Matches a well-formed postcode: exactly 4 digits. */
440	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
441	
442	    /**
443	     * Whether {@code owner}'s postcode is acceptable. Postcode is optional: a null postcode is always
444	     * accepted. When present it must be a 4-digit value and, when the owner's city maps to a known
445	     * region, must fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099,
446	     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode. The region-to-range
447	     * table lives on {@link Owner#postcodeRangeForRegion(String)} and is shared, not duplicated here.
448	     */
449	    private static boolean isPostcodeValidForCity(Owner owner) {
450	        String postcode = owner.getPostcode();
451	        if (postcode == null) {
452	            return true;
453	        }
454	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
455	            return false;
456	        }
457	        int[] range = Owner.postcodeRangeForRegion(owner.getRegion());
458	        if (range == null) {
459	            return true;
460	        }
461	        int value = Integer.parseInt(postcode);
462	        return value >= range[0] && value <= range[1];
463	    }
464	
465	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
466	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
467	
468	    /**
469	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
470	     * code are kept when present; otherwise country code '+61' is assumed and a single
471	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
472	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
473	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
474	     * Returns {@code null} when the number cannot form a valid E.164 value.
475	     */
476	    private static String normalizeTelephone(String telephone) {
477	        if (telephone == null) {
478	            return null;
479	        }
480	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
481	        String e164;
482	        if (cleaned.startsWith("+")) {
483	            e164 = cleaned;
484	        } else {
485	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
486	            e164 = "+61" + national;
487	        }
488	        if (!E164_PATTERN.matcher(e164).matches()) {
489	            return null;
490	        }
491	        return hasValidNationalNumberLength(e164) ? e164 : null;
492	    }
493	
494	    /**
495	     * Whether the national number of a well-formed E.164 value has the length required for its
496	     * country code. The country-code length table lives on {@link Owner#nationalNumberLength(String)}
497	     * and is shared, not duplicated here; a country code carrying no length rule is accepted.
498	     */
499	    private static boolean hasValidNationalNumberLength(String e164) {
500	        String countryCode = Owner.countryCodeOf(e164);
501	        if (countryCode == null) {
502	            return true;
503	        }
504	        return e164.length() - countryCode.length() == Owner.nationalNumberLength(countryCode);
505	    }
506	
507	    /**
508	     * Compute and assign the derived attributes carried by a newly registered owner: the customer
509	     * code, membership number, household id, namesake count and household member count. Each is
510	     * derived from the owner's already-normalized fields and the existing owner population, so this
511	     * must run before the owner is saved, while the counts still exclude the owner being created.
512	     *
513	     * <p>{@code declaredMember} is true when the owner was created into an existing household by
514	     * setting {@code sharesHousehold}: such an owner is a declared, not a suspected, household member,
515	     * so it is never flagged as a possible duplicate; otherwise the usual possible-duplicate check
516	     * runs (and, since a create that reaches here shares no existing household, does not flag it).
517	     */
518	    private void assignRegistrationAttributes(Owner owner, boolean declaredMember) {
519	        owner.setCustomerCode(generateCustomerCode(owner));
520	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
521	        owner.setHouseholdId(householdId(owner));
522	        owner.setNamesakeCount(countNamesakes(owner));
523	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
524	        owner.setMembershipLevelCap(membershipLevelCapForHousehold(owner));
525	        if (declaredMember) {
526	            owner.setPossibleDuplicate(false);
527	            owner.setPossibleDuplicateOf(null);
528	        } else {
529	            assignPossibleDuplicate(owner);
530	        }
531	    }
532	
533	    /**
534	     * Flag {@code owner} as a possible duplicate when, though not a hard duplicate (its create having
535	     * already cleared the {@link #isDuplicate} identity gate), it shares an existing owner's postcode
536	     * and last-name {@link #soundex(String) Soundex} yet resolves to a different {@link #identityKey}.
537	     * Sets {@code possibleDuplicate} accordingly and, when true, {@code possibleDuplicateOf} to the
538	     * matching owner's id. Runs before save, against the existing owner population.
539	     */
540	    private void assignPossibleDuplicate(Owner owner) {
541	        Integer matchId = findPossibleDuplicateOf(owner);
542	        owner.setPossibleDuplicate(matchId != null);
543	        owner.setPossibleDuplicateOf(matchId);
544	    }
545	
546	    /**
547	     * The id of an existing owner that shares {@code owner}'s postcode and last-name
548	     * {@link #soundex(String) Soundex} but resolves to a different {@link #identityKey}, or
549	     * {@code null} when there is none. Because the telephone is part of the identity key, two owners
550	     * with the same last name and postcode but different telephones differ in key and so match here,
551	     * making the later a soft (possible) duplicate rather than a hard conflict. When several match,
552	     * the lowest id is returned. An owner without a postcode never matches.
553	     */
554	    private Integer findPossibleDuplicateOf(Owner owner) {
555	        String postcode = owner.getPostcode();
556	        if (postcode == null) {
557	            return null;
558	        }
559	        String soundex = soundex(owner.getLastName());
560	        String identityKey = owner.getIdentityKey();
561	        return this.clinicService.findAllOwners().stream()
562	            .filter(existing -> !existing.isDeleted())
563	            .filter(existing -> existing.getId() != null
564	                && postcode.equals(existing.getPostcode())
565	                && soundex(existing.getLastName()).equals(soundex)
566	                && !identityKey.equals(existing.getIdentityKey()))
567	            .map(Owner::getId)
568	            .min(Integer::compareTo)
569	            .orElse(null);
570	    }
571	
572	    /**
573	     * Build {@code owner}'s customer code '<REGION>-<HASH8>': REGION is the region code derived from
574	     * the owner's postcode ({@link Owner#getRegion()}) and HASH8 the first 8 upper-case hex
575	     * characters of SHA-256 over the owner's already-normalized telephone concatenated with the
576	     * owner's last name (e.g. 'NSW-1A2B3C4D'). The identity is otherwise a pure function of the
577	     * region and the (telephone, last name) pair; only when the computed code collides with an
578	     * existing owner's customer code is it de-duplicated by appending '-<n>' with the smallest
579	     * {@code n} of 2 or more that makes it unique (e.g. 'NSW-1A2B3C4D-2').
580	     */
581	    private String generateCustomerCode(Owner owner) {
582	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
583	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
584	        String hash8 = Owner.sha256Hex(telephone + lastName).substring(0, 8);
585	        String base = owner.getRegion() + "-" + hash8;
586	        return deduplicateCustomerCode(base);
587	    }
588	
589	    /**
590	     * De-duplicate a computed customer code against the existing owner population: when {@code base}
591	     * is not already in use it is returned unchanged; otherwise '-<n>' is appended with the smallest
592	     * {@code n} of 2 or more that yields a code no existing owner carries.
593	     */
594	    private String deduplicateCustomerCode(String base) {
595	        Set<String> existing = this.clinicService.findAllOwners().stream()
596	            .map(Owner::getCustomerCode)
597	            .filter(code -> code != null)
598	            .collect(java.util.stream.Collectors.toSet());
599	        if (!existing.contains(base)) {
600	            return base;
601	        }
602	        int n = 2;
603	        while (existing.contains(base + "-" + n)) {
604	            n++;
605	        }
606	        return base + "-" + n;
607	    }
608	
609	    /**
610	     * The number of existing owners registered in {@code city}, compared case-insensitively
611	     * with collapsed whitespace.
612	     */
613	    private int countOwnersInCity(String city) {
614	        String normalized = normalizeHouseholdField(city);
615	        return (int) this.clinicService.findAllOwners().stream()
616	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
617	            .count();
618	    }
619	
620	    /**
621	     * The number of existing owners in {@code owner}'s city other than {@code owner} itself, compared
622	     * case-insensitively with collapsed whitespace. This is the count of owners already present in the
623	     * city that a newly created owner joins, mirroring the basis of the per-city create gate.
624	     */
625	    private long countOtherOwnersInCity(Owner owner) {
626	        String normalized = normalizeHouseholdField(owner.getCity());
627	        return this.clinicService.findAllOwners().stream()
628	            .filter(existing -> existing.getId() == null || !existing.getId().equals(owner.getId()))
629	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
630	            .count();
631	    }
632	
633	    /**
634	     * The effective registration date to store for a new owner: the date supplied on the request
635	     * when present, otherwise the current server date, in either case rolled forward to a business
636	     * day so it never falls on a weekend or public holiday (rolled forward to the next such day).
637	     * This single point of resolution is what every registration-date-derived value (the stored
638	     * date, the membership number's year segment, the per-day create-limit) is computed from.
639	     */
640	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
641	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
642	        return toBusinessDay(date);
643	    }
644	
645	    /**
646	     * The fixed list of public holidays that a registration date must not fall on. A date landing
647	     * on one of these is rolled forward, exactly as weekends are.
648	     */
649	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
650	        LocalDate.of(2026, 1, 1),
651	        LocalDate.of(2026, 1, 26),
652	        LocalDate.of(2026, 4, 25),
653	        LocalDate.of(2026, 12, 25),
654	        LocalDate.of(2026, 12, 28));
655	
656	    /**
657	     * Roll {@code date} forward to the next business day: a Saturday, Sunday, or listed public
658	     * holiday is advanced day by day until it lands on a non-holiday weekday, which is returned
659	     * unchanged.
660	     */
661	    private static LocalDate toBusinessDay(LocalDate date) {
662	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
663	                || PUBLIC_HOLIDAYS.contains(date)) {
664	            date = date.plusDays(1);
665	        }
666	        return date;
667	    }
668	
669	    /**
670	     * Build the membership number '<customerCode>-M<YY>' where YY is the two-digit
671	     * {@link Owner#fiscalYearSegment(LocalDate) fiscal-year segment} of the business-day-adjusted
672	     * {@code registrationDate} (e.g. 'NSW-1A2B3C4D-M27'). The fiscal-year segment lives on
673	     * {@link Owner} and is shared, not duplicated here.
674	     */
675	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
676	        return customerCode + "-M" + Owner.fiscalYearSegment(registrationDate);
677	    }
678	
679	    /**
680	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
681	     * last name, compared case-insensitively.
682	     */
683	    private int countNamesakes(Owner owner) {
684	        String firstName = normalizeHouseholdField(owner.getFirstName());
685	        String lastName = normalizeHouseholdField(owner.getLastName());
686	        return (int) this.clinicService.findAllOwners().stream()
687	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
688	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
689	            .count();
690	    }
691	
692	    /**
693	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
694	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
695	     * unusually high daily signup volume.
696	     */
697	    private boolean isBulkSignupWarning() {
698	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
699	    }
700	
701	    /** The number of existing owners whose registration date is {@code date}. */
702	    private int countOwnersRegisteredOn(LocalDate date) {
703	        return (int) this.clinicService.findAllOwners().stream()
704	            .filter(existing -> date.equals(existing.getRegistrationDate()))
705	            .count();
706	    }
707	
708	    /**
709	     * The single derived key all duplicate detection flows through: the lower-case hex SHA-256 of
710	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, formed from the
711	     * owner's already-normalized fields (the email is already lower-cased, the telephone already in
712	     * E.164 form, and the last name reduced to its {@link #soundex(String) Soundex} code). Because
713	     * the telephone is part of the key, two owners with the same last name and postcode but
714	     * different telephones resolve to different keys and are both allowed (the later one becoming a
715	     * possible duplicate rather than a hard conflict).
716	     */
717	    private static String identityKey(Owner owner) {
718	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
719	        String email = owner.getEmail() == null ? "" : owner.getEmail();
720	        String key = telephone + "|" + email + "|" + soundex(owner.getLastName());
721	        return Owner.sha256HexLower(key);
722	    }
723	
724	    /**
725	     * Whether {@code owner}'s {@link #identityKey} equals a non-deleted existing owner's, which is
726	     * the sole duplicate condition: the previously separate telephone, email and household checks -
727	     * including the household-duplicate check derived from the {@code householdId} - are now all
728	     * expressed through this one identity key, so only an exact key match is a duplicate and a create
729	     * that trips it is rejected with {@code 409 CONFLICT}. Soft-deleted owners are ignored.
730	     */
731	    private boolean isDuplicate(Owner owner) {
732	        String key = owner.getIdentityKey();
733	        return this.clinicService.findAllOwners().stream()
734	            .filter(existing -> !existing.isDeleted())
735	            .map(Owner::getIdentityKey)
736	            .filter(existing -> existing != null)
737	            .anyMatch(key::equals);
738	    }
739	
740	    /** Common street-type abbreviations expanded during address normalization. */
741	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
742	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
743	
744	    /**
745	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
746	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
747	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
748	     * string when {@code address} is null or blank after normalization.
749	     */
750	    private static String normalizeAddress(String address) {
751	        if (address == null) {
752	            return "";
753	        }
754	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
755	        if (collapsed.isEmpty()) {
756	            return "";
757	        }
758	        StringBuilder sb = new StringBuilder(collapsed.length());
759	        for (String token : collapsed.split(" ")) {
760	            if (sb.length() > 0) {
761	                sb.append(' ');
762	            }
763	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
764	        }
765	        return sb.toString();
766	    }
767	
768	    /**
769	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
770	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
771	     */
772	    private static String normalizeHouseholdField(String value) {
773	        if (value == null) {
774	            return "";
775	        }
776	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
777	    }
778	
779	    /**
780	     * The American Soundex code of {@code value}: the retained first letter followed by up to three
781	     * digits encoding the remaining consonants, right-padded with zeros to length four. Non-letters
782	     * are ignored, adjacent letters coding to the same digit (including when separated by 'H' or 'W')
783	     * are coded once, and vowels (with 'Y') act as separators. Returns the empty string when
784	     * {@code value} holds no letters. Phonetically similar last names share a code, which is what the
785	     * identity key and the possible-duplicate soft match compare on.
786	     */
787	    private static String soundex(String value) {
788	        if (value == null) {
789	            return "";
790	        }
791	        StringBuilder letters = new StringBuilder();
792	        for (char c : value.toCharArray()) {
793	            if (c < 128 && Character.isLetter(c)) {
794	                letters.append(Character.toUpperCase(c));
795	            }
796	        }
797	        if (letters.length() == 0) {
798	            return "";
799	        }
800	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
801	        char previous = soundexDigit(letters.charAt(0));
802	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
803	            char c = letters.charAt(i);
804	            if (c == 'H' || c == 'W') {
805	                continue;
806	            }
807	            char digit = soundexDigit(c);
808	            if (digit != '0' && digit != previous) {
809	                code.append(digit);
810	            }
811	            previous = digit;
812	        }
813	        while (code.length() < 4) {
814	            code.append('0');
815	        }
816	        return code.toString();
817	    }
818	
819	    /** The Soundex digit for an upper-case letter, or {@code '0'} for letters that are not coded. */
820	    private static char soundexDigit(char c) {
821	        switch (c) {
822	            case 'B': case 'F': case 'P': case 'V':
823	                return '1';
824	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
825	                return '2';
826	            case 'D': case 'T':
827	                return '3';
828	            case 'L':
829	                return '4';
830	            case 'M': case 'N':
831	                return '5';
832	            case 'R':
833	                return '6';
834	            default:
835	                return '0';
836	        }
837	    }
838	
839	    /**
840	     * Existing owners that share {@code owner}'s household, i.e. resolve to the same
841	     * {@link #householdId(Owner) householdId}. Household membership is defined by that single derived
842	     * key rather than re-derived from the underlying fields here, so the household is described in one
843	     * place and every household-keyed value stays consistent with it.
844	     */
845	    private List<Owner> findHousemates(Owner owner) {
846	        String householdId = householdId(owner);
847	        return this.clinicService.findAllOwners().stream()
848	            .filter(existing -> !existing.isDeleted())
849	            .filter(existing -> householdId(existing).equals(householdId))
850	            .toList();
851	    }
852	
853	    /**
854	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
855	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
856	     */
857	    private int countHouseholdMembers(Owner owner) {
858	        return findHousemates(owner).size() + 1;
859	    }
860	
861	    /**
862	     * The membership level ceiling for a newly registered {@code owner}, derived from the household it
863	     * joins: one above the current maximum {@link Owner#getMembershipLevel() membershipLevel} among the
864	     * existing housemates (owners sharing the same {@code householdId}), so a new owner's reported level
865	     * can never exceed one above the household's current best. Returns {@code null} - meaning no ceiling
866	     * applies - when the owner has no existing household member.
867	     */
868	    private Integer membershipLevelCapForHousehold(Owner owner) {
869	        OptionalInt maxLevel = findHousemates(owner).stream()
870	            .mapToInt(Owner::getMembershipLevel)
871	            .max();
872	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
873	    }
874	
875	    /**
876	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
877	     * same last name (compared case-insensitively with collapsed whitespace) and postcode. It is the
878	     * first 12 hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode} (the empty
879	     * string standing in for a missing postcode), so housemates always resolve to the same value
880	     * regardless of registration order, and owners sharing a last name and postcode share it
881	     * automatically.
882	     */
883	    private static String householdId(Owner owner) {
884	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
885	        String key = normalizeHouseholdField(owner.getLastName()) + "|" + postcode;
886	        return Owner.sha256Hex(key).substring(0, 12);
887	    }
888	}
