587	     *  or {@code null} when it is {@code null} or begins with no recognised country code. */
588	    public static String countryCodeOf(String telephone) {
589	        if (telephone == null) {
590	            return null;
591	        }
592	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
593	            if (telephone.startsWith(countryCode)) {
594	                return countryCode;
