607	    /** The single Luhn check digit (0-9) over the decimal digits contained in {@code value}, scanning
608	     *  right to left and doubling every second digit; non-digit characters are ignored and a null or
609	     *  digit-free value yields {@code 0}. Shared by the derived {@link #getCheckDigit()} and the
610	     *  controller that stamps a check digit into an owner's identifier, so the Luhn rule lives here
611	     *  once and is not duplicated. */
612	    public static int luhnCheckDigit(String value) {
613	        int sum = 0;
614	        boolean doubling = true;
615	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
616	            char c = value.charAt(i);
617	            if (c < '0' || c > '9') {
618	                continue;
619	            }
620	            int digit = c - '0';
621	            if (doubling) {
622	                digit *= 2;
623	                if (digit > 9) {
624	                    digit -= 9;
625	                }
626	            }
627	            sum += digit;
628	            doubling = !doubling;
629	        }
630	        return (10 - (sum % 10)) % 10;
631	    }
