633	    /** The upper-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters; the
634	     *  upper-case rendering of {@link #sha256HexLower(String)}. */
635	    public static String sha256Hex(String input) {
636	        return sha256HexLower(input).toUpperCase(Locale.ROOT);
637	    }
