639	    /** The lower-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters. */
640	    public static String sha256HexLower(String input) {
641	        try {
642	            byte[] digest = MessageDigest.getInstance("SHA-256")
643	                .digest(input.getBytes(StandardCharsets.UTF_8));
644	            StringBuilder sb = new StringBuilder(digest.length * 2);
645	            for (byte b : digest) {
646	                sb.append(String.format("%02x", b));
647	            }
648	            return sb.toString();
649	        }
650	        catch (NoSuchAlgorithmException e) {
651	            throw new IllegalStateException("SHA-256 not available", e);
652	        }
653	    }
