440	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
441	
442	    /**
443	     * Whether {@code owner}'s postcode is acceptable. Postcode is optional: a null postcode is always
444	     * accepted. When present it must be a 4-digit value and, when the owner's city maps to a known
445	     * region, must fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099,
446	     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode. The region-to-range
447	     * table lives on {@link Owner#postcodeRangeForRegion(String)} and is shared, not duplicated here.
448	     */
449	    private static boolean isPostcodeValidForCity(Owner owner) {
450	        String postcode = owner.getPostcode();
451	        if (postcode == null) {
452	            return true;
453	        }
454	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
455	            return false;
456	        }
457	        int[] range = Owner.postcodeRangeForRegion(owner.getRegion());
458	        if (range == null) {
459	            return true;
460	        }
461	        int value = Integer.parseInt(postcode);
462	        return value >= range[0] && value <= range[1];
463	    }
