465	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
466	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
467	
468	    /**
469	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
470	     * code are kept when present; otherwise country code '+61' is assumed and a single
471	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
472	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
473	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
474	     * Returns {@code null} when the number cannot form a valid E.164 value.
475	     */
476	    private static String normalizeTelephone(String telephone) {
477	        if (telephone == null) {
478	            return null;
479	        }
480	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
481	        String e164;
482	        if (cleaned.startsWith("+")) {
483	            e164 = cleaned;
484	        } else {
485	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
486	            e164 = "+61" + national;
487	        }
488	        if (!E164_PATTERN.matcher(e164).matches()) {
489	            return null;
490	        }
491	        return hasValidNationalNumberLength(e164) ? e164 : null;
492	    }
493	
494	    /**
495	     * Whether the national number of a well-formed E.164 value has the length required for its
496	     * country code. The country-code length table lives on {@link Owner#nationalNumberLength(String)}
497	     * and is shared, not duplicated here; a country code carrying no length rule is accepted.
498	     */
499	    private static boolean hasValidNationalNumberLength(String e164) {
500	        String countryCode = Owner.countryCodeOf(e164);
501	        if (countryCode == null) {
502	            return true;
503	        }
504	        return e164.length() - countryCode.length() == Owner.nationalNumberLength(countryCode);
505	    }
