507	    /**
508	     * Compute and assign the derived attributes carried by a newly registered owner: the customer
509	     * code, membership number, household id, namesake count and household member count. Each is
510	     * derived from the owner's already-normalized fields and the existing owner population, so this
511	     * must run before the owner is saved, while the counts still exclude the owner being created.
512	     *
513	     * <p>{@code declaredMember} is true when the owner was created into an existing household by
514	     * setting {@code sharesHousehold}: such an owner is a declared, not a suspected, household member,
515	     * so it is never flagged as a possible duplicate; otherwise the usual possible-duplicate check
516	     * runs (and, since a create that reaches here shares no existing household, does not flag it).
517	     */
518	    private void assignRegistrationAttributes(Owner owner, boolean declaredMember) {
519	        owner.setCustomerCode(generateCustomerCode(owner));
520	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
521	        owner.setHouseholdId(householdId(owner));
522	        owner.setNamesakeCount(countNamesakes(owner));
523	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
524	        owner.setMembershipLevelCap(membershipLevelCapForHousehold(owner));
525	        if (declaredMember) {
526	            owner.setPossibleDuplicate(false);
527	            owner.setPossibleDuplicateOf(null);
528	        } else {
529	            assignPossibleDuplicate(owner);
530	        }
531	    }
