546	    /**
547	     * The id of an existing owner that shares {@code owner}'s postcode and last-name
548	     * {@link #soundex(String) Soundex} but resolves to a different {@link #identityKey}, or
549	     * {@code null} when there is none. Because the telephone is part of the identity key, two owners
550	     * with the same last name and postcode but different telephones differ in key and so match here,
551	     * making the later a soft (possible) duplicate rather than a hard conflict. When several match,
552	     * the lowest id is returned. An owner without a postcode never matches.
553	     */
554	    private Integer findPossibleDuplicateOf(Owner owner) {
555	        String postcode = owner.getPostcode();
556	        if (postcode == null) {
557	            return null;
558	        }
559	        String soundex = soundex(owner.getLastName());
560	        String identityKey = owner.getIdentityKey();
561	        return this.clinicService.findAllOwners().stream()
562	            .filter(existing -> !existing.isDeleted())
563	            .filter(existing -> existing.getId() != null
564	                && postcode.equals(existing.getPostcode())
565	                && soundex(existing.getLastName()).equals(soundex)
566	                && !identityKey.equals(existing.getIdentityKey()))
567	            .map(Owner::getId)
568	            .min(Integer::compareTo)
569	            .orElse(null);
570	    }
