572	    /**
573	     * Build {@code owner}'s customer code '<REGION>-<HASH8>': REGION is the region code derived from
574	     * the owner's postcode ({@link Owner#getRegion()}) and HASH8 the first 8 upper-case hex
575	     * characters of SHA-256 over the owner's already-normalized telephone concatenated with the
576	     * owner's last name (e.g. 'NSW-1A2B3C4D'). The identity is otherwise a pure function of the
577	     * region and the (telephone, last name) pair; only when the computed code collides with an
578	     * existing owner's customer code is it de-duplicated by appending '-<n>' with the smallest
579	     * {@code n} of 2 or more that makes it unique (e.g. 'NSW-1A2B3C4D-2').
580	     */
581	    private String generateCustomerCode(Owner owner) {
582	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
583	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
584	        String hash8 = Owner.sha256Hex(telephone + lastName).substring(0, 8);
585	        String base = owner.getRegion() + "-" + hash8;
586	        return deduplicateCustomerCode(base);
587	    }
588	
589	    /**
590	     * De-duplicate a computed customer code against the existing owner population: when {@code base}
591	     * is not already in use it is returned unchanged; otherwise '-<n>' is appended with the smallest
592	     * {@code n} of 2 or more that yields a code no existing owner carries.
593	     */
594	    private String deduplicateCustomerCode(String base) {
595	        Set<String> existing = this.clinicService.findAllOwners().stream()
596	            .map(Owner::getCustomerCode)
597	            .filter(code -> code != null)
598	            .collect(java.util.stream.Collectors.toSet());
599	        if (!existing.contains(base)) {
600	            return base;
601	        }
602	        int n = 2;
603	        while (existing.contains(base + "-" + n)) {
604	            n++;
605	        }
606	        return base + "-" + n;
607	    }
