645	    /**
646	     * The fixed list of public holidays that a registration date must not fall on. A date landing
647	     * on one of these is rolled forward, exactly as weekends are.
648	     */
649	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
650	        LocalDate.of(2026, 1, 1),
651	        LocalDate.of(2026, 1, 26),
652	        LocalDate.of(2026, 4, 25),
653	        LocalDate.of(2026, 12, 25),
654	        LocalDate.of(2026, 12, 28));
