656	    /**
657	     * Roll {@code date} forward to the next business day: a Saturday, Sunday, or listed public
658	     * holiday is advanced day by day until it lands on a non-holiday weekday, which is returned
659	     * unchanged.
660	     */
661	    private static LocalDate toBusinessDay(LocalDate date) {
662	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
663	                || PUBLIC_HOLIDAYS.contains(date)) {
664	            date = date.plusDays(1);
665	        }
666	        return date;
667	    }
