708	    /**
709	     * The single derived key all duplicate detection flows through: the lower-case hex SHA-256 of
710	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, formed from the
711	     * owner's already-normalized fields (the email is already lower-cased, the telephone already in
712	     * E.164 form, and the last name reduced to its {@link #soundex(String) Soundex} code). Because
713	     * the telephone is part of the key, two owners with the same last name and postcode but
714	     * different telephones resolve to different keys and are both allowed (the later one becoming a
715	     * possible duplicate rather than a hard conflict).
716	     */
717	    private static String identityKey(Owner owner) {
718	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
719	        String email = owner.getEmail() == null ? "" : owner.getEmail();
720	        String key = telephone + "|" + email + "|" + soundex(owner.getLastName());
721	        return Owner.sha256HexLower(key);
722	    }
