724	    /**
725	     * Whether {@code owner}'s {@link #identityKey} equals a non-deleted existing owner's, which is
726	     * the sole duplicate condition: the previously separate telephone, email and household checks -
727	     * including the household-duplicate check derived from the {@code householdId} - are now all
728	     * expressed through this one identity key, so only an exact key match is a duplicate and a create
729	     * that trips it is rejected with {@code 409 CONFLICT}. Soft-deleted owners are ignored.
730	     */
731	    private boolean isDuplicate(Owner owner) {
732	        String key = owner.getIdentityKey();
733	        return this.clinicService.findAllOwners().stream()
734	            .filter(existing -> !existing.isDeleted())
735	            .map(Owner::getIdentityKey)
736	            .filter(existing -> existing != null)
737	            .anyMatch(key::equals);
738	    }
