768	    /**
769	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
770	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
771	     */
772	    private static String normalizeHouseholdField(String value) {
773	        if (value == null) {
774	            return "";
775	        }
776	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
777	    }
