883	    private static String householdId(Owner owner) {
884	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
885	        String key = normalizeHouseholdField(owner.getLastName()) + "|" + postcode;
886	        return Owner.sha256Hex(key).substring(0, 12);
