300	     * Whether {@code email}'s domain (the part after the last '@') is on the disposable-domain
301	     * blocklist, compared case-insensitively. The email is already normalized to lower case by the
302	     * caller, so a simple membership test against {@link #DISPOSABLE_EMAIL_DOMAINS} suffices.
303	     */
304	    private static boolean isDisposableEmailDomain(String email) {
305	        int at = email.lastIndexOf('@');
306	        if (at < 0) {
307	            return false;
308	        }
309	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));

